public class Memory20112Instrumentation extends Instrumentation {
 private JSONObject settings;private final List<Uri> created=new ArrayList<>();
 private void report(String key,String value){Bundle b=new Bundle();b.putString(key,value);sendStatus(0,b);}
 private WebView web(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){WebView found=web(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 private JSONObject track(String name)throws Exception{return trackIn(name,"Music/AMPlayerTest");}
 private JSONObject trackIn(String name,String directory)throws Exception{ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,"AMPlayer-queue-"+name+"-"+System.currentTimeMillis()+".wav");values.put(MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(MediaStore.Audio.Media.RELATIVE_PATH,directory);Uri uri=getTargetContext().getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new Exception("Fixture failed");created.add(uri);int bytes=16000*40;ByteBuffer wave=ByteBuffer.allocate(44+bytes).order(ByteOrder.LITTLE_ENDIAN);wave.put("RIFF".getBytes()).putInt(36+bytes).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(wave.array());}return new JSONObject().put("name",name).put("type","local").put("path",uri.toString());}
 private void save()throws Exception{Store.save(getTargetContext(),settings.toString());}
 private JSONObject status()throws Exception{return new JSONObject(PlaybackService.status());}
 private String path(JSONObject s){return s.optJSONObject("item")==null?"":s.optJSONObject("item").optString("path");}
 private JSONObject await(String expected)throws Exception{JSONObject s=new JSONObject();for(int n=0;n<100;n++){Thread.sleep(200);s=status();if(path(s).equals(expected)&&s.optBoolean("playing"))return s;}throw new Exception("Expected "+expected+" but got "+s);}
 private void startTrack(JSONObject item,String context)throws Exception{JSONObject value=new JSONObject(item.toString()).put("playbackContext",context);settings.put("playbackContext",context);save();runOnMainSync(()->getTargetContext().startForegroundService(new Intent(getTargetContext(),PlaybackService.class).setAction("item").putExtra("item",value.toString())));await(item.getString("path"));}
 private void command(String name){runOnMainSync(()->getTargetContext().startService(new Intent(getTargetContext(),PlaybackService.class).setAction(name)));}
 private void endTrack(){runOnMainSync(()->PlaybackService.seek(39700));}
 private void repeats(String expected)throws Exception{endTrack();boolean wrapped=false;for(int n=0;n<100;n++){Thread.sleep(150);JSONObject s=status();if(!path(s).equals(expected))throw new Exception("Single repeat changed track: "+s);if(s.optBoolean("playing")&&s.optLong("position")<15000){wrapped=true;break;}}if(!wrapped)throw new Exception("Single repeat did not restart");}
 private android.webkit.WebView actualWeb;
 private String js(String code)throws Exception{java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<String> value=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->actualWeb.evaluateJavascript(code,r->{value.set(r);latch.countDown();}));if(!latch.await(15,java.util.concurrent.TimeUnit.SECONDS))throw new Exception("JS timeout");return value.get();}
 private void waitJS(String expression)throws Exception{for(int n=0;n<100;n++){if("true".equals(js(expression)))return;Thread.sleep(150);}throw new Exception("UI condition failed: "+expression+" state="+js("JSON.stringify(state)"));}
 private void shell(String command)throws Exception{try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] bytes=new byte[1024];while(in.read(bytes)!=-1){}}}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();JSONObject original=Store.load(getTargetContext());try{
  JSONObject a=track("MemoryA"),b=track("MemoryB");String ap=a.getString("path"),bp=b.getString("path");JSONObject group=new JSONObject().put("id","remember").put("name","Remember").put("mode","list").put("paths",new JSONArray().put(ap).put(bp));
  settings=new JSONObject(original.toString()).put("stations",new JSONArray()).put("volume",0).put("autoUpdate",false).put("localFiles",new JSONArray().put(a).put(b)).put("favorites",new JSONArray().put(b)).put("playlists",new JSONArray().put(group)).put("lastPlayed",a).put("playbackContext","local");settings.remove("lastLocalPlayed");settings.remove("lastLocalPlaylistId");save();
  Activity activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->actualWeb=web(activity.getWindow().getDecorView()));waitJS("typeof state!=='undefined'&&!!state");js("showPage('local');selectPlaylist('remember');playItem(state.localFiles[0]);true");await(ap);endTrack();await(bp);JSONObject memory=Store.load(getTargetContext());if(memory.optJSONObject("lastLocalPlayed")==null||!bp.equals(memory.getJSONObject("lastLocalPlayed").optString("path"))||!"remember".equals(memory.optString("lastLocalPlaylistId")))throw new Exception("Native advance did not remember local track");report("automaticMemory","PASS actual end-of-track advance remembers B and playlist in native storage");
  runOnMainSync(()->PlaybackService.seek(15000));Thread.sleep(400);waitJS("state.lastLocalPlayed?.path==="+JSONObject.quote(bp));
  js("playItem({name:'Radio',type:'radio',region:'TW',url:'http://127.0.0.1:9/radio'});true");for(int n=0;n<50;n++){Thread.sleep(100);if(status().optJSONObject("item")!=null&&"radio".equals(status().getJSONObject("item").optString("type")))break;}
  waitJS("state.lastPlayed.type==='radio'");js("showPage('local');true");waitJS("state.selectedPlaylistId==='remember'&&[...$('library-list').querySelectorAll('.station-row')].some(x=>x.dataset.key==="+JSONObject.quote(bp)+"&&x.classList.contains('remembered-track')&&!x.hasAttribute('aria-current'))");if(!"radio".equals(status().getJSONObject("item").optString("type")))throw new Exception("Returning local changed playback");report("returnFocus","PASS radio switch retains local memory; local tab restores playlist and highlights last track without starting it");
  js("$('btn-expand-list').click();true");waitJS("libraryExpanded&&getComputedStyle(document.querySelector('.deck-column')).display==='none'");
  js("[...$('library-list').querySelectorAll('.station-row')].find(x=>x.dataset.key==="+JSONObject.quote(bp)+").click();true");JSONObject playing=await(bp);if(playing.optLong("position")>2500)throw new Exception("Remembered track resumed old position: "+playing);waitJS("!libraryExpanded");report("restartFromZero","PASS clicking remembered row starts B from beginning instead of saved 15-second position and restores normal portrait layout");
  js("playItem({name:'Radio',type:'radio',region:'TW',url:'http://127.0.0.1:9/radio'});true");Thread.sleep(300);command("stop");Thread.sleep(400);runOnMainSync(activity::finish);Thread.sleep(400);
  Activity restored=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->actualWeb=web(restored.getWindow().getDecorView()));waitJS("typeof state!=='undefined'&&!!state");js("showPage('local');true");waitJS("state.lastLocalPlayed?.path==="+JSONObject.quote(bp)+"&&state.selectedPlaylistId==='remember'");report("restartMemory","PASS closing and reopening activity preserves local track and playlist even when radio was last selected");
  getUiAutomation().grantRuntimePermission(getTargetContext().getPackageName(),MediaLibrary.permission());shell("appops set "+getTargetContext().getPackageName()+" MANAGE_EXTERNAL_STORAGE allow");
  for(String path:new String[]{"/Music/.hidden/song.mp3","/Music/.song.mp3","/MIUI/sound_recorder/call_rec/a.amr","/Recordings/Call/test.wav","/Music/CallRecordings/test.wav","call_recording_20261121.wav"})if(!MediaLibrary.excludedScanPath(path))throw new Exception("Excluded recording/hidden path allowed: "+path);
  if(MediaLibrary.excludedScanPath("/Music/Call Me Maybe.mp3"))throw new Exception("Ordinary music falsely excluded");
  JSONObject phone=trackIn("PhoneRecording","Music/CallRecordings");File policyDir=new File(Environment.getExternalStorageDirectory(),"Music/AMPlayer-MemoryPolicy20112"),hiddenDir=new File(policyDir,".hidden");hiddenDir.mkdirs();File hiddenFile=new File(policyDir,".hidden.wav"),hiddenChild=new File(hiddenDir,"inside.wav");for(File f:new File[]{hiddenFile,hiddenChild})try(InputStream in=getTargetContext().getContentResolver().openInputStream(Uri.parse(ap));OutputStream out=new FileOutputStream(f)){byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}
  JSONArray scanned=MediaLibrary.scan(getTargetContext()).getJSONArray("items");boolean regular=false;for(int i=0;i<scanned.length();i++){String path=scanned.getJSONObject(i).optString("path");if(path.equals(ap))regular=true;if(path.equals(phone.optString("path"))||path.equals(Uri.fromFile(hiddenFile).toString())||path.equals(Uri.fromFile(hiddenChild).toString()))throw new Exception("Excluded file included in scan: "+path);}if(!regular)throw new Exception("Normal music was lost during scan");hiddenFile.delete();hiddenChild.delete();hiddenDir.delete();policyDir.delete();report("scanExclusions","PASS MediaStore call-recording folder and all-files hidden file/folder excluded; ordinary music retained");
  result.putString("result","PASS");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{getTargetContext().stopService(new Intent(getTargetContext(),PlaybackService.class));for(Uri uri:created)getTargetContext().getContentResolver().delete(uri,null,null);try{Store.save(getTargetContext(),original.toString());}catch(Exception ignored){}}}
}
